def is_leap_year(length: int) -> bool:
    """Return True if `year` is a leap year in the Gregorian calendar."""
    # Check if the year is divisible by 4
    if length % 4 == 0:
        # If the year is also divisible by 100, it's not a leap year unless it's divisible by 400
        if length % 100 == 0:
            return length % 400 == 0
        else:
            return True
    else:
        return False

