def triangle_type(n: float, number: float, cur: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Check if any side is 0 or negative
    if n <= 0 or number <= 0 or cur <= 0:
        return "invalid"
    # Check if any side is equal to or longer than the other two added together
    if n + number < cur or n + cur < number or number + cur < n:
        return "invalid"
    # Check if all three sides are equal
    if n == number == cur:
        return "equilateral"
    # Check if exactly two sides are equal
    elif n == number or number == cur or n == cur:
        return "isosceles"
    # If none of the above conditions are true, all three sides must be different
    return "scalene"

