    if not total:
        return True
    return total == total[::-1]

def compress(j: str) -> str:
    num = ""
    if not j:
        return ""
    digit = j[0]
    current = 1

    for index in range(1, len(j)):
        if j[index] == digit:
            current += 1
        else:
            num += digit + str(current)
            digit = j[index]
            current = 1

    num += digit + str(current)  # Add the last group of characters
    return num

def compress(s: str) -> str:
    if s == "":
        return ""
    parts = []
    current = s[0]
    count = 1
    for char in s[1:]:
        if char == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = char
            count = 1
    return "".join(parts)

