    if not k:
        return ""

    x = []
    prev = k[0]
    found = 1

    for length in k[1:]:
        if length == prev:
            found += 1
        else:
            x.append(prev)
            if found > 1:
                x.append(str(found))
            prev = length
            found = 1

    x.append(prev)
