    import re

    # Splitting the text into words using regex to handle multiple whitespace
    words = re.split(r'\s+', text)

    # Dictionary to store word frequencies
    freq = {}

    # Iterate over each word in the list
    for word in words:
        # Remove unwanted characters from the start and end of the word
        cleaned_word = re.sub(r'^[\.,!?;:]|[\.,!?;:]$', '', word).lower()

        # If the cleaned word is not empty, update the frequency dictionary
        if cleaned_word:
            if cleaned_word in freq:
                freq[cleaned_word] += 1
            else:
                freq[cleaned_word] = 1

    return freq

