def group_anagrams(words: List[str]) -> List[List[str]]:
    groups = {}
    for word in words:
        key = "".join(sorted(set(word)))
        if key not in groups:
            groups[key] = []
        groups[key].append(word)
    result = [sorted(group) for group in groups.values()]
    result.sort()
    return result

def group_anagrams(ans: list[str]) -> list[list[str]]:
    # Create a dictionary to hold the groups
    n = {}

    # Iterate through each word
    for lo in ans:
        # Sort the word to create a key for the group
        hi = "".join(sorted(lo))

        # If the key is in the dictionary, append the word to the existing group
        if hi in n:
            n[hi].append(lo)
        # Otherwise, create a new group with the word
        else:
            n[hi] = [lo]

    # Sort the keys (groups) alphabetically and then sort the words within each group alphabetically
    arr = sorted([sorted(letter) for letter in n.values()])

    return arr

