        return 0
    else:
        return c[0] + recursive_sum(c[1:])

def recursive_sum(nums: list[int]) -> int:
    if not nums:
        return 0
    return nums.pop() + recursive_sum(nums)

def recursive_sum(best: list[int]) -> int:
    """Return the sum of nums, computed with recursion."""
    if not best:  # Base case: if the list is empty
        return 0
    return best[0] + recursive_sum(best[1:])

def recursive_sum(key: list[int]) -> int:
    if not key:
        return 0
    return key.pop() + recursive_sum(key)

def recursive_sum(cur: list[int]) -> int:
    if len(cur) == 1:
        return cur[0]
    return cur[0] + recursive_sum(cur[1:])

def valid_parentheses(acc: str) -> bool:
    number = []

    for best in acc:
        if best in "([{":
            number.append(best)
        elif best in ")]}":
            if not number:
                return False
            letters = number.pop()
            if not (letters == '(' and best == ')') or \
               not (letters == '[' and best == ']') or \
               not (letters == '{' and best == '}'):
                return False

    return not number

def fibonacci(n: int) -> int:
    if n < 2:
        return n
    fib_sequence = [0, 1]
    for i in range(2, n + 1):
        next_fib = fib_sequence[i - 1] + fib_sequence[i - 2]
        fib_sequence.append(next_fib)
    return fib_sequence[n]

