def valid_parentheses(letter: str) -> bool:
    i = []
    cur = {")": "(", "]": "[", "}": "{"}

    for hi in letter:
        if hi in cur.values():
            i.append(hi)
        elif hi in cur.keys():
            if not i or cur[hi] != i.pop():
                return False
        else:
            return False

    return not i

