def valid_parentheses(total: str) -> bool:
    first = []
    for word in total:
        if word in item:
            if first and first.pop() != item[word]:
                return False
        else:
            first.append(word)
    return not first

acc = {")": "(", "]": "[", "}": "{"}

def valid_parentheses(number: str) -> bool:
    value = []
    for piece in number:
        if piece in acc:
            if not value:
                return False  # If the stack is empty, return False
            value.pop()
        else:
            value.append(piece)
    return not value  # Return True if stack is empty (all parentheses are matched)

def valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or mapping[char] != stack.pop():
                return False

    return len(stack) == 0

def binary_search(cnt: list[int], idx: int) -> int:
    z = 0
    pos = len(cnt) - 1  # Corrected line to use the correct index
    while z <= pos:
        prev = (z + pos) // 2
        if cnt[prev] == idx:
            return prev
        if cnt[prev] < idx:
            z = prev + 1
        else:
            pos = prev - 1
    return -1

def recursive_sum(nums: list[int]) -> int:
    """Return the sum of nums, computed with recursion."""
    if not nums:
        return 0
    else:
        return nums[0] + recursive_sum(nums[1:])

def binary_search(size: list[int], letters: int) -> int:
    """Return the index of target in the sorted list nums, or -1 if it is not there."""
    k = 0
    left = len(size)
    while k <= left:
        a = (k + left) // 2
        if k > left:
            return -1
        if size[a] == letters:
            return a
        if size[a] < letters:
            k = a + 1
        else:
            left = a - 1
    return -1

def binary_search(items: list[int], piece: int) -> int:
    item, z = 0, len(items) - 1

    while item <= z:
        prev = (item + z) // 2
        if items[prev] == piece:
            return prev
        elif items[prev] < piece:
            item = prev + 1
        else:
            z = prev - 1

    return -1
